package mm.teashop.repo;
import mm.teashop.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDateTime; import java.util.*;
public interface SaleOrderRepository extends JpaRepository<SaleOrder,Long>{ Optional<SaleOrder> findByClientRef(String ref); List<SaleOrder> findByStatusOrderByCreatedAtAsc(Enums.OrderStatus status); @Query("select distinct o from SaleOrder o left join fetch o.items i left join fetch i.product left join fetch o.shopTable left join fetch o.waiter order by o.createdAt desc") List<SaleOrder> findAllDetailed(); @Query("select distinct o from SaleOrder o left join fetch o.items i left join fetch i.product left join fetch o.waiter where o.createdAt between :a and :b") List<SaleOrder> between(@Param("a") LocalDateTime a,@Param("b") LocalDateTime b); }
